// UVM 1.2 Inherited Doc Topics for uvm_reg_field
if(window.__registerUvmDocTopics){window.__registerUvmDocTopics("uvm_reg_field",[{"n":"value","k":"variable","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-1","s":"src_view/reg/uvm_reg_field.svh.html#L45","h":"<div class=\"CVariable\" data-anchor=\"uvm_reg_field.value\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L45\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"45\">value</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">rand</span> <span class=\"sv-uvm-type\">uvm_reg_data_t</span> <span class=\"sv-ident\">value</span>\n  </td></tr></table></blockquote><div class=CBody><p>Mirrored field value.&nbsp; This value can be sampled in a functional coverage model or constrained when randomized.</p></div></div></div>"},{"n":"new","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-3","s":"src_view/reg/uvm_reg_field.svh.html#L87","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.new\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L87\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"87\">new</a></h3><div class=\"method-meta-bar\"><span class=\"badge-override\" title=\"Overrides base method from uvm_object\">Overrides uvm_object</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-proto-name\">new</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">name</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;uvm_reg_field&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Create a new field instance</p><p>This method should not be used directly.&nbsp; The <i>uvm_reg_field::type_id::create()</i> factory method should be used instead.</p></div></div></div>"},{"n":"configure","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-4","s":"src_view/reg/uvm_reg_field.svh.html#L112","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.configure\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L112\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"112\">configure</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=4><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">configure</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">parent</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">size</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">lsb_pos</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">access</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">volatile</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">reset</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">has_reset</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">is_rand</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap></td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">individually_accessible</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=4><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Instance-specific configuration</p><p>Specify the <i>parent</i> register of this field, its <i>size</i> in bits, the position of its least-significant bit within the register relative to the least-significant bit of the register, its <i>access</i> policy, volatility, &ldquo;HARD&rdquo; <i>reset</i> value, whether the field value is actually reset (the <i>reset</i> value is ignored if <i>FALSE</i>), whether the field value may be randomized and whether the field is the only one to occupy a byte lane in the register.</p><p>See <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-12\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-12\" data-target-id=\"doc-nav-item-12\" class=LMethod  >set_access</a> for a specification of the pre-defined field access policies.</p><p>If the field access policy is a pre-defined policy and NOT one of &ldquo;RW&rdquo;, &ldquo;WRC&rdquo;, &ldquo;WRS&rdquo;, &ldquo;WO&rdquo;, &ldquo;W1&rdquo;, or &ldquo;WO1&rdquo;, the value of <i>is_rand</i> is ignored and the rand_mode() for the field instance is turned off since it cannot be written.</p></div></div></div>"},{"n":"get_name","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-6","s":"src_view/reg/uvm_reg_field.svh.html#L127","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L127\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"127\">get_name</a></h3><div class=CBody><p>Get the simple name</p><p>Return the simple object name of this field</p></div></div></div>"},{"n":"get_full_name","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-7","s":"src_view/reg/uvm_reg_field.svh.html#L142","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_full_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L142\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"142\">get_full_name</a></h3><div class=\"method-meta-bar\"><span class=\"badge-override\" title=\"Overrides base method from uvm_object\">Overrides uvm_object</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">get_full_name</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Get the hierarchical name</p><p>Return the hierarchal name of this field The base of the hierarchical name is the root block.</p></div></div></div>"},{"n":"get_parent","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-8","s":"src_view/reg/uvm_reg_field.svh.html#L149","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_parent\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L149\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"149\">get_parent</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_reg</span> <span class=\"sv-proto-name\">get_parent</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Get the parent register</p></div></div></div>"},{"n":"get_lsb_pos","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-9","s":"src_view/reg/uvm_reg_field.svh.html#L162","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_lsb_pos\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L162\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"162\">get_lsb_pos</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-type\">unsigned</span> <span class=\"sv-proto-name\">get_lsb_pos</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Return the position of the field</p><p>Returns the index of the least significant bit of the field in the register that instantiates it.&nbsp; An offset of 0 indicates a field that is aligned with the least-significant bit of the register.</p></div></div></div>"},{"n":"get_n_bits","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-10","s":"src_view/reg/uvm_reg_field.svh.html#L169","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_n_bits\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L169\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"169\">get_n_bits</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-type\">unsigned</span> <span class=\"sv-proto-name\">get_n_bits</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the width, in number of bits, of the field.</p></div></div></div>"},{"n":"get_max_size","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-11","s":"src_view/reg/uvm_reg_field.svh.html#L175","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_max_size\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L175\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"175\">get_max_size</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-type\">unsigned</span> <span class=\"sv-proto-name\">get_max_size</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the width, in number of bits, of the largest field.</p></div></div></div>"},{"n":"set_access","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-12","s":"src_view/reg/uvm_reg_field.svh.html#L222","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.set_access\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L222\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"222\">set_access</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">set_access</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">mode</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Modify the access policy of the field</p><p>Modify the access policy of the field to the specified one and return the previous access policy.</p><p>The pre-defined access policies are as follows.&nbsp; The effect of a read operation are applied after the current value of the field is sampled.&nbsp; The read operation will return the current value, not the value affected by the read operation (if any).</p><table border=0 cellspacing=0 cellpadding=0 class=CDescriptionList><tr><td class=CDLEntry>&rdquo;RO&rdquo;</td><td class=CDLDescription>W: no effect, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;RW&rdquo;</td><td class=CDLDescription>W: as-is, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;RC&rdquo;</td><td class=CDLDescription>W: no effect, R: clears all bits</td></tr><tr><td class=CDLEntry>&rdquo;RS&rdquo;</td><td class=CDLDescription>W: no effect, R: sets all bits</td></tr><tr><td class=CDLEntry>&rdquo;WRC&rdquo;</td><td class=CDLDescription>W: as-is, R: clears all bits</td></tr><tr><td class=CDLEntry>&rdquo;WRS&rdquo;</td><td class=CDLDescription>W: as-is, R: sets all bits</td></tr><tr><td class=CDLEntry>&rdquo;WC&rdquo;</td><td class=CDLDescription>W: clears all bits, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;WS&rdquo;</td><td class=CDLDescription>W: sets all bits, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;WSRC&rdquo;</td><td class=CDLDescription>W: sets all bits, R: clears all bits</td></tr><tr><td class=CDLEntry>&rdquo;WCRS&rdquo;</td><td class=CDLDescription>W: clears all bits, R: sets all bits</td></tr><tr><td class=CDLEntry>&rdquo;W1C&rdquo;</td><td class=CDLDescription>W: 1/0 clears/no effect on matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W1S&rdquo;</td><td class=CDLDescription>W: 1/0 sets/no effect on matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W1T&rdquo;</td><td class=CDLDescription>W: 1/0 toggles/no effect on matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W0C&rdquo;</td><td class=CDLDescription>W: 1/0 no effect on/clears matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W0S&rdquo;</td><td class=CDLDescription>W: 1/0 no effect on/sets matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W0T&rdquo;</td><td class=CDLDescription>W: 1/0 no effect on/toggles matching bit, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;W1SRC&rdquo;</td><td class=CDLDescription>W: 1/0 sets/no effect on matching bit, R: clears all bits</td></tr><tr><td class=CDLEntry>&rdquo;W1CRS&rdquo;</td><td class=CDLDescription>W: 1/0 clears/no effect on matching bit, R: sets all bits</td></tr><tr><td class=CDLEntry>&rdquo;W0SRC&rdquo;</td><td class=CDLDescription>W: 1/0 no effect on/sets matching bit, R: clears all bits</td></tr><tr><td class=CDLEntry>&rdquo;W0CRS&rdquo;</td><td class=CDLDescription>W: 1/0 no effect on/clears matching bit, R: sets all bits</td></tr><tr><td class=CDLEntry>&rdquo;WO&rdquo;</td><td class=CDLDescription>W: as-is, R: error</td></tr><tr><td class=CDLEntry>&rdquo;WOC&rdquo;</td><td class=CDLDescription>W: clears all bits, R: error</td></tr><tr><td class=CDLEntry>&rdquo;WOS&rdquo;</td><td class=CDLDescription>W: sets all bits, R: error</td></tr><tr><td class=CDLEntry>&rdquo;W1&rdquo;</td><td class=CDLDescription>W: first one after <i>HARD</i> reset is as-is, other W have no effects, R: no effect</td></tr><tr><td class=CDLEntry>&rdquo;WO1&rdquo;</td><td class=CDLDescription>W: first one after <i>HARD</i> reset is as-is, other W have no effects, R: error</td></tr><tr><td class=CDLEntry>&rdquo;NOACCESS&rdquo;</td><td class=CDLDescription>W: no effect, R: no effect</td></tr></table><p>It is important to remember that modifying the access of a field will make the register model diverge from the specification that was used to create it.</p></div></div></div>"},{"n":"define_access","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-13","s":"src_view/reg/uvm_reg_field.svh.html#L242","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.define_access\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L242\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"242\">define_access</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">define_access</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">name</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Define a new access policy value</p><p>Because field access policies are specified using string values, there is no way for SystemVerilog to verify if a specific access value is valid or not.&nbsp; To help catch typing errors, user-defined access values must be defined using this method to avoid begin reported as an invalid access policy.</p><p>The name of field access policies are always converted to all uppercase.</p><p>Returns TRUE if the new access policy was not previously defined.&nbsp; Returns FALSE otherwise but does not issue an error message.</p></div></div></div>"},{"n":"get_access","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-14","s":"src_view/reg/uvm_reg_field.svh.html#L263","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_access\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L263\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"263\">get_access</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">get_access</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Get the access policy of the field</p><p>Returns the current access policy of the field when written and read through the specified address <i>map</i>.&nbsp; If the register containing the field is mapped in multiple address map, an address map must be specified.&nbsp; The access policy of a field from a specific address map may be restricted by the register&rsquo;s access policy in that address map.&nbsp; For example, a RW field may only be writable through one of the address maps and read-only through all of the other maps.&nbsp; If the field access contradicts the map&rsquo;s access value (field access of WO, and map access value of RO, etc), the method&rsquo;s return value is NOACCESS.</p></div></div></div>"},{"n":"is_known_access","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-15","s":"src_view/reg/uvm_reg_field.svh.html#L274","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.is_known_access\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L274\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"274\">is_known_access</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">is_known_access</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Check if access policy is a built-in one.</p><p>Returns TRUE if the current access policy of the field, when written and read through the specified address <i>map</i>, is a built-in access policy.</p></div></div></div>"},{"n":"set_volatility","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-16","s":"src_view/reg/uvm_reg_field.svh.html#L284","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.set_volatility\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L284\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"284\">set_volatility</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_volatility</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">volatile</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Modify the volatility of the field to the specified one.</p><p>It is important to remember that modifying the volatility of a field will make the register model diverge from the specification that was used to create it.</p></div></div></div>"},{"n":"is_volatile","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-17","s":"src_view/reg/uvm_reg_field.svh.html#L298","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.is_volatile\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L298\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"298\">is_volatile</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">is_volatile</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Indicates if the field value is volatile</p><p>UVM uses the IEEE 1685-2009 IP-XACT definition of &ldquo;volatility&rdquo;.&nbsp; If TRUE, the value of the register is not predictable because it may change between consecutive accesses.&nbsp; This typically indicates a field whose value is updated by the DUT.&nbsp; The nature or cause of the change is not specified.&nbsp; If FALSE, the value of the register is not modified between consecutive accesses.</p></div></div></div>"},{"n":"set","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-19","s":"src_view/reg/uvm_reg_field.svh.html#L333","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.set\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L333\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"333\">set</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Set the desired value for this field</p><p>It sets the desired value of the field to the specified <i>value</i> modified by the field access policy.&nbsp; It does not actually set the value of the field in the design, only the desired value in the abstraction class.&nbsp; Use the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg::update()</a> method to update the actual register with the desired value or the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-27\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-27\" data-target-id=\"doc-nav-item-27\" class=LMethod  >uvm_reg_field::write()</a> method to actually write the field and update its mirrored value.</p><p>The final desired value in the mirror is a function of the field access policy and the set value, just like a normal physical write operation to the corresponding bits in the hardware.&nbsp; As such, this method (when eventually followed by a call to <a href=\"__ROOT_REL__docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg::update()</a>) is a zero-time functional replacement for the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-27\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-27\" data-target-id=\"doc-nav-item-27\" class=LMethod  >uvm_reg_field::write()</a> method.&nbsp; For example, the desired value of a read-only field is not modified by this method and the desired value of a write-once field can only be set if the field has not yet been written to using a physical (for example, front-door) write operation.</p><p>Use the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg_field::predict()</a> to modify the mirrored value of the field.</p></div></div></div>"},{"n":"get","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-20","s":"src_view/reg/uvm_reg_field.svh.html#L356","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L356\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"356\">get</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_reg_data_t</span> <span class=\"sv-proto-name\">get</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Return the desired value of the field</p><p>It does not actually read the value of the field in the design, only the desired value in the abstraction class.&nbsp; Unless set to a different value using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >uvm_reg_field::set()</a>, the desired value and the mirrored value are identical.</p><p>Use the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-28\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-28\" data-target-id=\"doc-nav-item-28\" class=LMethod  >uvm_reg_field::read()</a> or <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-30\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-30\" data-target-id=\"doc-nav-item-30\" class=LMethod  >uvm_reg_field::peek()</a> method to get the actual field value.</p><p>If the field is write-only, the desired/mirrored value is the value last written and assumed to reside in the bits implementing it.&nbsp; Although a physical read operation would something different, the returned value is the actual content.</p></div></div></div>"},{"n":"get_mirrored_value","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-21","s":"src_view/reg/uvm_reg_field.svh.html#L373","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_mirrored_value\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L373\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"373\">get_mirrored_value</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_reg_data_t</span> <span class=\"sv-proto-name\">get_mirrored_value</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Return the mirrored value of the field</p><p>It does not actually read the value of the field in the design, only the mirrored value in the abstraction class.</p><p>If the field is write-only, the desired/mirrored value is the value last written and assumed to reside in the bits implementing it.&nbsp; Although a physical read operation would something different, the returned value is the actual content.</p></div></div></div>"},{"n":"reset","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-22","s":"src_view/reg/uvm_reg_field.svh.html#L391","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.reset\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L391\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"391\">reset</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">reset</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;HARD&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Reset the desired/mirrored value for this field.</p><p>It sets the desired and mirror value of the field to the reset event specified by <i>kind</i>.&nbsp; If the field does not have a reset value specified for the specified reset <i>kind</i> the field is unchanged.</p><p>It does not actually reset the value of the field in the design, only the value mirrored in the field abstraction class.</p><p>Write-once fields can be modified after a &ldquo;HARD&rdquo; reset operation.</p></div></div></div>"},{"n":"get_reset","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-23","s":"src_view/reg/uvm_reg_field.svh.html#L403","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_reset\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L403\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"403\">get_reset</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_reg_data_t</span> <span class=\"sv-proto-name\">get_reset</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;HARD&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Get the specified reset value for this field</p><p>Return the reset value for this field for the specified reset <i>kind</i>.&nbsp; Returns the current field value is no reset value has been specified for the specified reset event.</p></div></div></div>"},{"n":"has_reset","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-24","s":"src_view/reg/uvm_reg_field.svh.html#L414","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.has_reset\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L414\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"414\">has_reset</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">has_reset</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;HARD&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">delete</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Check if the field has a reset value specified</p><p>Return TRUE if this field has a reset value specified for the specified reset <i>kind</i>.&nbsp; If <i>delete</i> is TRUE, removes the reset value, if any.</p></div></div></div>"},{"n":"set_reset","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-25","s":"src_view/reg/uvm_reg_field.svh.html#L425","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.set_reset\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L425\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"425\">set_reset</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_reset</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;HARD&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Specify or modify the reset value for this field</p><p>Specify or modify the reset value for this field corresponding to the cause specified by <i>kind</i>.</p></div></div></div>"},{"n":"needs_update","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-26","s":"src_view/reg/uvm_reg_field.svh.html#L443","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.needs_update\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L443\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"443\">needs_update</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">needs_update</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Check if the abstract model contains different desired and mirrored values.</p><p>If a desired field value has been modified in the abstraction class without actually updating the field in the DUT, the state of the DUT (more specifically what the abstraction class <i>thinks</i> the state of the DUT is) is outdated.&nbsp; This method returns TRUE if the state of the field in the DUT needs to be updated to match the desired value.&nbsp; The mirror values or actual content of DUT field are not modified.&nbsp; Use the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg::update()</a> to actually update the DUT field.</p></div></div></div>"},{"n":"write","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-27","s":"src_view/reg/uvm_reg_field.svh.html#L477","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.write\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L477\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"477\">write</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">write</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_status_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">status</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_path_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">path</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_DEFAULT_PATH,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_sequence_base</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">parent</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">prior</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> -1,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">extension</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Write the specified value in this field</p><p>Write <i>value</i> in the DUT field that corresponds to this abstraction class instance using the specified access <i>path</i>.&nbsp; If the register containing this field is mapped in more than one address map, an address <i>map</i> must be specified if a physical access is used (front-door access).&nbsp; If a back-door access path is used, the effect of writing the field through a physical access is mimicked.&nbsp; For example, read-only bits in the field will not be written.</p><p>The mirrored value will be updated using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg_field::predict()</a> method.</p><p>If a front-door access is used, and if the field is the only field in a byte lane and if the physical interface corresponding to the address map used to access the field support byte-enabling, then only the field is written.&nbsp; Otherwise, the entire register containing the field is written, and the mirrored values of the other fields in the same register are used in a best-effort not to modify their value.</p><p>If a backdoor access is used, a peek-modify-poke process is used. in a best-effort not to modify the value of the other fields in the register.</p></div></div></div>"},{"n":"read","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-28","s":"src_view/reg/uvm_reg_field.svh.html#L517","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.read\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L517\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"517\">read</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">read</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_status_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">status</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_path_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">path</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_DEFAULT_PATH,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_sequence_base</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">parent</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">prior</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> -1,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">extension</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Read the current value from this field</p><p>Read and return <i>value</i> from the DUT field that corresponds to this abstraction class instance using the specified access <i>path</i>.&nbsp; If the register containing this field is mapped in more than one address map, an address <i>map</i> must be specified if a physical access is used (front-door access).&nbsp; If a back-door access path is used, the effect of reading the field through a physical access is mimicked.&nbsp; For example, clear-on-read bits in the field will be set to zero.</p><p>The mirrored value will be updated using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg_field::predict()</a> method.</p><p>If a front-door access is used, and if the field is the only field in a byte lane and if the physical interface corresponding to the address map used to access the field support byte-enabling, then only the field is read.&nbsp; Otherwise, the entire register containing the field is read, and the mirrored values of the other fields in the same register are updated.</p><p>If a backdoor access is used, the entire containing register is peeked and the mirrored value of the other fields in the register is updated.</p></div></div></div>"},{"n":"poke","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-29","s":"src_view/reg/uvm_reg_field.svh.html#L541","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.poke\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L541\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"541\">poke</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">poke</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_status_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">status</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_sequence_base</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">parent</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">extension</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Deposit the specified value in this field</p><p>Deposit the value in the DUT field corresponding to this abstraction class instance, as-is, using a back-door access.&nbsp; A peek-modify-poke process is used in a best-effort not to modify the value of the other fields in the register.</p><p>The mirrored value will be updated using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg_field::predict()</a> method.</p></div></div></div>"},{"n":"peek","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-30","s":"src_view/reg/uvm_reg_field.svh.html#L565","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.peek\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L565\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"565\">peek</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">peek</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_status_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">status</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_sequence_base</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">parent</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">extension</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Read the current value from this field</p><p>Sample the value in the DUT field corresponding to this abstraction class instance using a back-door access.&nbsp; The field value is sampled, not modified.</p><p>Uses the HDL path for the design abstraction specified by <i>kind</i>.</p><p>The entire containing register is peeked and the mirrored value of the other fields in the register are updated using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >uvm_reg_field::predict()</a> method.</p></div></div></div>"},{"n":"mirror","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-31","s":"src_view/reg/uvm_reg_field.svh.html#L598","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.mirror\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L598\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"598\">mirror</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">mirror</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">output</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_status_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">status</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_check_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">check</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_NO_CHECK,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_path_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">path</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_DEFAULT_PATH,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_sequence_base</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">parent</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">prior</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> -1,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">extension</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Read the field and update/check its mirror value</p><p>Read the field and optionally compared the readback value with the current mirrored value if <i>check</i> is <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" class=LConstant  >UVM_CHECK</a>.&nbsp; The mirrored value will be updated using the <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >predict()</a> method based on the readback value.</p><p>The <i>path</i> argument specifies whether to mirror using the  <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_FRONTDOOR\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_FRONTDOOR\" class=LConstant  >UVM_FRONTDOOR</a> (<a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-28\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-28\" data-target-id=\"doc-nav-item-28\" class=LMethod  >read</a>) or <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" class=LConstant  >UVM_BACKDOOR</a> (<a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-30\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-30\" data-target-id=\"doc-nav-item-30\" class=LMethod  >peek()</a>).</p><p>If <i>check</i> is specified as <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" class=LConstant  >UVM_CHECK</a>, an error message is issued if the current mirrored value does not match the readback value, unless <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-32\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-32\" data-target-id=\"doc-nav-item-32\" class=LMethod  >set_compare</a> was used disable the check.</p><p>If the containing register is mapped in multiple address maps and physical access is used (front-door access), an address <i>map</i> must be specified.&nbsp; For write-only fields, their content is mirrored and optionally checked only if a UVM_BACKDOOR access path is used to read the field.</p></div></div></div>"},{"n":"set_compare","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-32","s":"src_view/reg/uvm_reg_field.svh.html#L617","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.set_compare\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L617\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"617\">set_compare</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_compare</span><span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_check_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">check</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">UVM_CHECK</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Sets the compare policy during a mirror update.&nbsp; The field value is checked against its mirror only when both the <i>check</i> argument in <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_block-svh.html#doc-nav-item-45\" data-doc-href=\"docs_view/reg/uvm_reg_block-svh.html#doc-nav-item-45\" data-target-id=\"doc-nav-item-45\" class=LMethod  >uvm_reg_block::mirror</a>, <a href=\"__ROOT_REL__docs_view/reg/uvm_reg-svh.html#doc-nav-item-36\" data-doc-href=\"docs_view/reg/uvm_reg-svh.html#doc-nav-item-36\" data-target-id=\"doc-nav-item-36\" class=LMethod  >uvm_reg::mirror</a>, or <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-31\" data-doc-href=\"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-31\" data-target-id=\"doc-nav-item-31\" class=LMethod  >uvm_reg_field::mirror</a> and the compare policy for the field is <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_CHECK\" class=LConstant  >UVM_CHECK</a>.</p></div></div></div>"},{"n":"get_compare","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-33","s":"src_view/reg/uvm_reg_field.svh.html#L624","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.get_compare\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L624\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"624\">get_compare</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_check_e</span> <span class=\"sv-proto-name\">get_compare</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the compare policy for this field.</p></div></div></div>"},{"n":"is_indv_accessible","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-34","s":"src_view/reg/uvm_reg_field.svh.html#L632","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.is_indv_accessible\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L632\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"632\">is_indv_accessible</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">is_indv_accessible</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_path_e</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">path</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">local_map</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Check if this field can be written individually, i.e. without affecting other fields in the containing register.</p></div></div></div>"},{"n":"predict","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-35","s":"src_view/reg/uvm_reg_field.svh.html#L661","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.predict\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L661\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"661\">predict</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">predict</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_data_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_byte_en_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">be</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> -1,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_predict_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">kind</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_PREDICT_DIRECT,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_path_e</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">path</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> UVM_FRONTDOOR,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_map</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">map</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> null,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">fname</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> &quot;&quot;,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">lineno</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"> 0</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Update the mirrored and desired value for this field.</p><p>Predict the mirror and desired value of the field based on the specified observed <i>value</i> on a bus using the specified address <i>map</i>.</p><p>If <i>kind</i> is specified as <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_READ\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_READ\" class=LConstant  >UVM_PREDICT_READ</a>, the value was observed in a read transaction on the specified address <i>map</i> or backdoor (if <i>path</i> is <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" class=LConstant  >UVM_BACKDOOR</a>).&nbsp; If <i>kind</i> is specified as <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_WRITE\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_WRITE\" class=LConstant  >UVM_PREDICT_WRITE</a>, the value was observed in a write transaction on the specified address <i>map</i> or backdoor (if <i>path</i> is <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_BACKDOOR\" class=LConstant  >UVM_BACKDOOR</a>).&nbsp; If <i>kind</i> is specified as <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_DIRECT\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_DIRECT\" class=LConstant  >UVM_PREDICT_DIRECT</a>, the value was computed and is updated as-is, without regard to any access policy.&nbsp; For example, the mirrored value of a read-only field is modified by this method if <i>kind</i> is specified as <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_DIRECT\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_PREDICT_DIRECT\" class=LConstant  >UVM_PREDICT_DIRECT</a>.</p><p>This method does not allow an update of the mirror (or desired) when the register containing this field is busy executing a transaction because the results are unpredictable and indicative of a race condition in the testbench.</p><p>Returns TRUE if the prediction was successful.</p></div></div></div>"},{"n":"pre_write","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-37","s":"src_view/reg/uvm_reg_field.svh.html#L718","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.pre_write\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L718\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"718\">pre_write</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">pre_write</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_item</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rw</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Called before field write.</p><p>If the specified data value, access <i>path</i> or address <i>map</i> are modified, the updated data value, access path or address map will be used to perform the register operation.&nbsp; If the <i>status</i> is modified to anything other than <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_IS_OK\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_IS_OK\" class=LConstant  >UVM_IS_OK</a>, the operation is aborted.</p><p>The field callback methods are invoked after the callback methods on the containing register.&nbsp; The registered callback methods are invoked after the invocation of this method.</p></div></div></div>"},{"n":"post_write","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-38","s":"src_view/reg/uvm_reg_field.svh.html#L734","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.post_write\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L734\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"734\">post_write</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">post_write</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_item</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rw</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Called after field write.</p><p>If the specified <i>status</i> is modified, the updated status will be returned by the register operation.</p><p>The field callback methods are invoked after the callback methods on the containing register.&nbsp; The registered callback methods are invoked before the invocation of this method.</p></div></div></div>"},{"n":"pre_read","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-39","s":"src_view/reg/uvm_reg_field.svh.html#L752","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.pre_read\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L752\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"752\">pre_read</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">pre_read</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_item</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rw</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Called before field read.</p><p>If the access <i>path</i> or address <i>map</i> in the <i>rw</i> argument are modified, the updated access path or address map will be used to perform the register operation.&nbsp; If the <i>status</i> is modified to anything other than <a href=\"__ROOT_REL__docs_view/reg/uvm_reg_model-svh.html#UVM_IS_OK\" data-doc-href=\"docs_view/reg/uvm_reg_model-svh.html#UVM_IS_OK\" class=LConstant  >UVM_IS_OK</a>, the operation is aborted.</p><p>The field callback methods are invoked after the callback methods on the containing register.&nbsp; The registered callback methods are invoked after the invocation of this method.</p></div></div></div>"},{"n":"post_read","k":"method","d":"docs_view/reg/uvm_reg_field-svh.html#doc-nav-item-40","s":"src_view/reg/uvm_reg_field.svh.html#L768","h":"<div class=\"CMethod\" data-anchor=\"uvm_reg_field.post_read\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/reg/uvm_reg_field.svh.html#L768\" class=\"src-code-link\" data-src-file=\"reg/uvm_reg_field.svh\" data-src-line=\"768\">post_read</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">task</span> <span class=\"sv-proto-name\">post_read</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_reg_item</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rw</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Called after field read.</p><p>If the specified readback data or~status~ in the <i>rw</i> argument is modified, the updated readback data or status will be returned by the register operation.</p><p>The field callback methods are invoked after the callback methods on the containing register.&nbsp; The registered callback methods are invoked before the invocation of this method.</p></div></div></div>"}]);}
